<script setup>
import {ref,watch} from 'vue';
import api from '../../services/api';
const props=defineProps({clientId:{type:Number,required:true}});
const data=ref(null),email=ref(''),confirmed=ref(false),busy=ref(false),error=ref(''),notice=ref('');let generation=0;
async function load(){const run=++generation;data.value=null;error.value='';try{const r=await api.get(`/dependent-portal/manage/${props.clientId}`,{skipGlobalLoading:true});if(run===generation)data.value=r.data;}catch(e){if(run===generation&&![403,409].includes(e.response?.status))error.value='Could not load personal portal access.';}}
async function act(action){if(busy.value)return;if(action==='revoke'&&!window.confirm('Turn off this dependent’s personal portal login? Their records will be kept.'))return;const run=generation;busy.value=true;error.value='';notice.value='';try{await api.post(`/dependent-portal/manage/${props.clientId}/${action}`,{email:email.value,confirmed:confirmed.value});if(run!==generation)return;await load();notice.value=action==='revoke'?'Personal portal access is turned off.':'Invitation sent to the dependent’s email address.';}catch(e){if(run===generation)error.value=e.response?.data?.error?.message||'Could not update personal portal access.';}finally{busy.value=false;}}
watch(()=>props.clientId,()=>{email.value='';confirmed.value=false;notice.value='';load();},{immediate:true});
</script>
<template><section v-if="data||error" class="dependent-invite"><h3>Their own portal login</h3><p>Invite this dependent with their own email address. They’ll see their appointments, learning materials, and messages. Their care team chooses which clinical records to share.</p><p class="privacy">Family billing, siblings, and parent-only conversations stay outside this login.</p>
<template v-if="data?.invitation"><p><strong>{{data.invitation.email}}</strong> · {{!data.invitation.active?'Access turned off':data.invitation.passwordSet?'Account set up':'Waiting for password setup'}}</p><div v-if="data.invitation.active" class="actions"><button :disabled="busy" @click="act('resend')">Resend invitation</button><button :disabled="busy" @click="act('revoke')">Turn off access</button></div><p v-else>Contact your care team to review or restore this login.</p></template>
<form v-else-if="data" @submit.prevent="act('invite')"><label>The dependent’s email<input v-model="email" type="email" required autocomplete="off" maxlength="254" /></label><label class="check"><input v-model="confirmed" type="checkbox" required />I am authorized to invite this dependent to their own portal.</label><button :disabled="busy||!confirmed">{{busy?'Sending…':'Send personal portal invitation'}}</button></form><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p></section></template>
<style scoped>.dependent-invite{padding:22px;margin:20px 0;border:1px solid #c9dbea;border-radius:14px;background:#f5f9fd;color:#193653}.dependent-invite p{line-height:1.5}.privacy{font-size:14px}.dependent-invite form>label{display:grid;gap:6px;margin:12px 0}.dependent-invite input[type=email]{padding:12px;border:1px solid #aabfd2;border-radius:8px;font:inherit;width:100%;box-sizing:border-box}.dependent-invite .check{display:flex;align-items:start;gap:10px}.dependent-invite button{padding:12px;border-radius:8px;border:1px solid #16477c;background:#16477c;color:white;font:inherit;cursor:pointer}.actions{display:flex;gap:10px;flex-wrap:wrap}[role=alert]{color:#a12222}button:disabled{opacity:.6}</style>
